<?php
namespace App\Http\Controllers\Api\V1;
use App\Exceptions\BusinessRuleException; use App\Http\Controllers\Controller; use App\Http\Requests\Finance\BankAccountRequest; use App\Http\Requests\Finance\BankTransactionRequest; use App\Http\Requests\Finance\ExpenseRequest; use App\Models\BankAccount; use App\Models\BankTransaction; use App\Models\Expense; use App\Services\AuditLogger; use App\Services\FinanceService; use App\Support\Dec; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class FinanceController extends Controller {
 public function __construct(private FinanceService $finance){}
 public function accounts(Request $r){$q=BankAccount::with('branch:id,name')->when($r->filled('search'),fn($q)=>$q->where(fn($x)=>$x->where('name','like','%'.$r->search.'%')->orWhere('account_number','like','%'.$r->search.'%')))->orderBy('name'); return $q->paginate(max(5,min((int)$r->query('per_page',20),100)))->through(function($a){$a->balance=Dec::str($this->finance->balanceUnits($a),2);return $a;});}
 public function storeAccount(BankAccountRequest $r){$data=$r->validated();$a=BankAccount::create($data);AuditLogger::log('bank.account.create',$a,null,$data);return response()->json($a,201);}
 public function updateAccount(BankAccountRequest $r,BankAccount $bank_account){$data=$r->validated(); if(isset($data['opening_balance']) && BankTransaction::where(fn($q)=>$q->where('from_account_id',$bank_account->id)->orWhere('to_account_id',$bank_account->id))->where('status','approved')->exists() && (string)$data['opening_balance']!==(string)$bank_account->opening_balance) return response()->json(['message'=>'Operatsiyalar mavjud: boshlang‘ich qoldiqni o‘zgartirib bo‘lmaydi.'],422); $old=$bank_account->only(array_keys($data));$bank_account->update($data);AuditLogger::log('bank.account.update',$bank_account,$old,$data);return response()->json($bank_account->fresh());}
 public function transactions(Request $r){return BankTransaction::with(['fromAccount:id,name,account_number','toAccount:id,name,account_number','cashbox:id,name'])->when($r->filled('status'),fn($q)=>$q->where('status',$r->status))->when($r->filled('type'),fn($q)=>$q->where('type',$r->type))->when($r->filled('date_from'),fn($q)=>$q->whereDate('created_at','>=',$r->date_from))->when($r->filled('date_to'),fn($q)=>$q->whereDate('created_at','<=',$r->date_to))->latest()->paginate(max(5,min((int)$r->query('per_page',20),100)));}
 public function storeTransaction(BankTransactionRequest $r){$d=$r->validated();if(!empty($d['client_token'])&&($old=BankTransaction::where('client_token',$d['client_token'])->first()))return response()->json($old);$t=BankTransaction::create($d+['number'=>'BNK-'.now()->format('YmdHis').'-'.Str::upper(Str::random(4)),'status'=>'draft','created_by'=>$r->user()->id]);AuditLogger::log('bank.transaction.create',$t,null,$t->only(['number','type','amount','status']));return response()->json($t,201);}
 public function approveTransaction(Request $r,BankTransaction $bank_transaction){try{return response()->json($this->finance->approveBank($bank_transaction,$r->user()));}catch(BusinessRuleException $e){return response()->json(['message'=>$e->getMessage()],422);}}
 public function cancelTransaction(Request $r,BankTransaction $bank_transaction){if($bank_transaction->status!=='draft')return response()->json(['message'=>'Tasdiqlangan operatsiyani o‘chirib bo‘lmaydi; buxgalteriya tuzatish hujjati kerak.'],422);$bank_transaction->update(['status'=>'cancelled']);AuditLogger::log('bank.cancel',$bank_transaction,['status'=>'draft'],['status'=>'cancelled']);return response()->json($bank_transaction);}
 public function expenses(Request $r){return Expense::with(['bankAccount:id,name','cashbox:id,name','branch:id,name'])->when($r->filled('status'),fn($q)=>$q->where('status',$r->status))->when($r->filled('category'),fn($q)=>$q->where('category','like','%'.$r->category.'%'))->when($r->filled('date_from'),fn($q)=>$q->whereDate('expense_date','>=',$r->date_from))->when($r->filled('date_to'),fn($q)=>$q->whereDate('expense_date','<=',$r->date_to))->latest('expense_date')->paginate(max(5,min((int)$r->query('per_page',20),100)));}
 public function storeExpense(ExpenseRequest $r){$d=$r->validated();$e=Expense::create($d+['number'=>'EXP-'.now()->format('YmdHis').'-'.Str::upper(Str::random(4)),'status'=>'draft','created_by'=>$r->user()->id]);AuditLogger::log('expenses.create',$e,null,$e->only(['number','category','amount','payment_method','status']));return response()->json($e,201);}
 public function approveExpense(Request $r,Expense $expense){try{return response()->json($this->finance->approveExpense($expense,$r->user()));}catch(BusinessRuleException $e){return response()->json(['message'=>$e->getMessage()],422);}}
 public function cancelExpense(Request $r,Expense $expense){if($expense->status!=='draft')return response()->json(['message'=>'Tasdiqlangan xarajatni o‘chirib bo‘lmaydi.'],422);$expense->update(['status'=>'cancelled']);AuditLogger::log('expenses.cancel',$expense,['status'=>'draft'],['status'=>'cancelled']);return response()->json($expense);}
}
